// Regrouper la vérification du panier vide de Swag Labs.
describe('Swag Labs cart', () => {
    // Se connecter avant le scénario avec la commande partagée.
    beforeEach(() => {
        // Ouvrir une session utilisateur standard sans ajouter d'article.
        cy.login();
    });

    // Fermer la session après le scénario.
    afterEach(() => {
        // Se déconnecter avec la commande partagée.
        cy.logout();
    });

    // Définir le scénario de consultation d'un panier vide.
    it('affiche un panier vide sans aucun article dans la liste', () => {
        // Ouvrir la page du panier.
        cy.get('[data-test="shopping-cart-link"]').should('be.visible').click();
        // Vérifier que le navigateur est sur la page du panier.
        cy.location('pathname').should('eq', '/cart.html');
        // Vérifier que le titre Your Cart est visible.
        cy.get('[data-test="secondary-header"]').should('be.visible').and('have.text', 'Your Cart');
        // Vérifier qu'aucun article n'est affiché dans la liste.
        cy.get('.cart_item').should('not.exist');
        // Vérifier que le badge du panier n'est pas affiché.
        cy.get('[data-test="shopping-cart-badge"]').should('not.exist');
    });
});
